42	/* global document, window */
43	
44	const CSS_TRANSITION_VENDOR = toCSSVendorPrefix(TRANSITION_VENDOR, 'transition');
45	const CSS_TRANSFORM_VENDOR = toCSSVendorPrefix(TRANSFORM_VENDOR, 'transform');
46	
47	// eslint-disable-next-line
48	const gCssText = `position:absolute;display:block;border-style:solid;white-space:nowrap;z-index:9999999;${env.transform3dSupported ? 'will-change:transform;' : ''}`;
49	
50	function mirrorPos(pos: string): string {
51	    pos = pos === 'left'
52	        ? 'right'
53	        : pos === 'right'
54	        ? 'left'
55	        : pos === 'top'
56	        ? 'bottom'
57	        : 'top';
58	    return pos;
59	}
60	
61	function assembleArrow(
62	    tooltipModel: Model<TooltipOption>,
63	    borderColor: ZRColor,
64	    arrowPosition: TooltipOption['position']
65	) {
66	    if (!isString(arrowPosition) || arrowPosition === 'inside') {
67	        return '';
68	    }
69	
70	    const backgroundColor = tooltipModel.get('backgroundColor');
71	    const borderWidth = tooltipModel.get('borderWidth');
72	
73	    borderColor = convertToColorString(borderColor);
74	    const arrowPos = mirrorPos(arrowPosition);
75	    const arrowSize = Math.max(Math.round(borderWidth) * 1.5, 6);
76	    let positionStyle = '';
77	    let transformStyle = CSS_TRANSFORM_VENDOR + ':';
78	    let rotateDeg;
79	    if (indexOf(['left', 'right'], arrowPos) > -1) {
80	        positionStyle += 'top:50%';
81	        transformStyle += `translateY(-50%) rotate(${rotateDeg = arrowPos === 'left' ? -225 : -45}deg)`;
82	    }
83	    else {
84	        positionStyle += 'left:50%';
85	        transformStyle += `translateX(-50%) rotate(${rotateDeg = arrowPos === 'top' ? 225 : 45}deg)`;
86	    }
87	    const rotateRadian = rotateDeg * Math.PI / 180;
88	    const arrowWH = arrowSize + borderWidth;
89	    const rotatedWH = arrowWH * Math.abs(Math.cos(rotateRadian)) + arrowWH * Math.abs(Math.sin(rotateRadian));
90	    const arrowOffset = Math.round(((rotatedWH - Math.SQRT2 * borderWidth) / 2
91	        + Math.SQRT2 * borderWidth - (rotatedWH - arrowWH) / 2) * 100) / 100;
92	    positionStyle += `;${arrowPos}:-${arrowOffset}px`;
93	
94	    const borderStyle = `${borderColor} solid ${borderWidth}px;`;
95	    const styleCss = [
96	        `position:absolute;width:${arrowSize}px;height:${arrowSize}px;z-index:-1;`,
97	        `${positionStyle};${transformStyle};`,
98	        `border-bottom:${borderStyle}`,
99	        `border-right:${borderStyle}`,
100	        `background-color:${backgroundColor};`
101	    ];
102	
103	    return `<div style="${styleCss.join('')}"></div>`;
104	}
105	
106	function assembleTransition(duration: number, onlyFadeTransition: boolean, enableDisplayTransition: boolean): string {
107	    const transitionCurve = 'cubic-bezier(0.23,1,0.32,1)';
108	    let transitionOption = '';
109	    let transitionText = '';
110	    if (enableDisplayTransition) {
111	        transitionOption = ` ${duration / 2}s ${transitionCurve}`;
112	        transitionText = `opacity${transitionOption},visibility${transitionOption}`;
113	    }
114	    if (!onlyFadeTransition) {
115	        transitionOption = ` ${duration}s ${transitionCurve}`;
116	        transitionText += (transitionText.length ? ',' : '') + (
117	            env.transformSupported
118	                ? `${CSS_TRANSFORM_VENDOR}${transitionOption}`
119	                : `,left${transitionOption},top${transitionOption}`
120	        );
121	    }
122	
123	    return CSS_TRANSITION_VENDOR + ':' + transitionText;
124	}
125	
126	function assembleTransform(x: number, y: number, toString?: boolean) {
127	    // If using float on style, the final width of the dom might
128	    // keep changing slightly while mouse move. So `toFixed(0)` them.
129	    const x0 = x.toFixed(0) + 'px';
130	    const y0 = y.toFixed(0) + 'px';
131	    // not support transform, use `left` and `top` instead.
132	    if (!env.transformSupported) {
133	        return toString
134	            ? `top:${y0};left:${x0};`
135	            : [['top', y0], ['left', x0]];
136	    }
137	    // support transform
138	    const is3d = env.transform3dSupported;
139	    const translate = `translate${is3d ? '3d' : ''}(${x0},${y0}${is3d ? ',0' : ''})`;
140	    return toString
141	        ? 'top:0;left:0;' + CSS_TRANSFORM_VENDOR + ':' + translate + ';'
142	        : [['top', 0], ['left', 0], [TRANSFORM_VENDOR, translate]];
143	}
144	
145	/**
146	 * @param {Object} textStyle
147	 * @return {string}
148	 * @inner
149	 */
150	function assembleFont(textStyleModel: Model<TooltipOption['textStyle']>): string {
151	    const cssText = [];
152	
153	    const fontSize = textStyleModel.get('fontSize');
154	    const color = textStyleModel.getTextColor();
155	
156	    color && cssText.push('color:' + color);
157	
158	    cssText.push('font:' + textStyleModel.getFont());
159	
160	    // @ts-ignore, leave it to the tooltip refactor.
161	    const lineHeight = retrieve2(textStyleModel.get('lineHeight'), Math.round(fontSize * 3 / 2));
162	
163	    fontSize
164	        && cssText.push('line-height:' + lineHeight + 'px');
165	
166	    const shadowColor = textStyleModel.get('textShadowColor');
167	    const shadowBlur = textStyleModel.get('textShadowBlur') || 0;
168	    const shadowOffsetX = textStyleModel.get('textShadowOffsetX') || 0;
169	    const shadowOffsetY = textStyleModel.get('textShadowOffsetY') || 0;
170	    shadowColor && shadowBlur
171	        && cssText.push('text-shadow:' + shadowOffsetX + 'px ' + shadowOffsetY + 'px '
172	            + shadowBlur + 'px ' + shadowColor);
173	
174	    each(['decoration', 'align'] as const, function (name) {
175	        const val = textStyleModel.get(name);
176	        val && cssText.push('text-' + name + ':' + val);
177	    });
178	
179	    return cssText.join(';');
180	}
181	
182	function assembleCssText(
183	    tooltipModel: Model<TooltipOption>,
184	    enableTransition: boolean,
185	    onlyFadeTransition: boolean,
186	    enableDisplayTransition: boolean
187	) {
188	    const cssText: string[] = [];
189	    const transitionDuration = tooltipModel.get('transitionDuration');
190	    const backgroundColor = tooltipModel.get('backgroundColor');
191	    const shadowBlur = tooltipModel.get('shadowBlur');
192	    const shadowColor = tooltipModel.get('shadowColor');
193	    const shadowOffsetX = tooltipModel.get('shadowOffsetX');
194	    const shadowOffsetY = tooltipModel.get('shadowOffsetY');
195	    const textStyleModel = tooltipModel.getModel('textStyle');
196	    const padding = getPaddingFromTooltipModel(tooltipModel, 'html');
197	    const boxShadow = `${shadowOffsetX}px ${shadowOffsetY}px ${shadowBlur}px ${shadowColor}`;
198	
199	    cssText.push('box-shadow:' + boxShadow);
200	    // Animation transition. Do not animate when transitionDuration <= 0.
201	    enableTransition && transitionDuration > 0
202	        && cssText.push(assembleTransition(transitionDuration, onlyFadeTransition, enableDisplayTransition));
203	
204	    if (backgroundColor) {
205	        cssText.push('background-color:' + backgroundColor);
206	    }
207	
208	    // Border style
209	    each(['width', 'color', 'radius'] as const, function (name) {
210	        const borderName = 'border-' + name;
211	        const camelCase = toCamelCase(borderName) as 'borderWidth' | 'borderColor' | 'borderRadius';
212	        const val = tooltipModel.get(camelCase);
213	        val != null
214	            && cssText.push(borderName + ':' + val + (name === 'color' ? '' : 'px'));
215	    });
216	
217	    // Text style
218	    cssText.push(assembleFont(textStyleModel));
219	
220	    // Padding
221	    if (padding != null) {
222	        cssText.push('padding:' + normalizeCssArray(padding).join('px ') + 'px');
223	    }
224	
225	    return cssText.join(';') + ';';
226	}
227	
228	// If not able to make, do not modify the input `out`.
229	function makeStyleCoord(
230	    out: number[],
231	    zr: ZRenderType,
232	    container: HTMLElement | null | undefined,
233	    zrX: number,
234	    zrY: number
235	) {
236	    const zrPainter = zr && zr.painter;
237	
238	    if (container) {
239	        const zrViewportRoot = zrPainter && zrPainter.getViewportRoot();
240	        if (zrViewportRoot) {
241	            // Some APPs might use scale on body, so we support CSS transform here.
242	            transformLocalCoord(out, zrViewportRoot, container, zrX, zrY);
243	        }
244	    }
245	    else {
246	        out[0] = zrX;
247	        out[1] = zrY;
248	        // xy should be based on canvas root. But tooltipContent is
249	        // the sibling of canvas root. So padding of ec container
250	        // should be considered here.
251	        const viewportRootOffset = zrPainter && (zrPainter as CanvasPainter | SVGPainter).getViewportRootOffset();
252	        if (viewportRootOffset) {
253	            out[0] += viewportRootOffset.offsetLeft;
254	            out[1] += viewportRootOffset.offsetTop;
255	        }
256	    }
257	
258	    out[2] = out[0] / zr.getWidth();
259	    out[3] = out[1] / zr.getHeight();
260	}
261	
262	interface TooltipContentOption {
263	    /**
264	     * Specify target container of the tooltip element.
265	     * Can either be an HTMLElement, CSS selector string, or a function that returns an HTMLElement.
266	     */
267	    appendTo: ((chartContainer: HTMLElement) => HTMLElement | undefined | null) | HTMLElement | string
268	}
269	
270	class TooltipHTMLContent {
271	
272	    el: HTMLDivElement;
273	
274	    private _api: ExtensionAPI;
275	    private _container: HTMLElement | undefined | null;
276	
277	    private _show: boolean = false;
278	
279	    private _styleCoord: [number, number, number, number] = [0, 0, 0, 0];
280	
281	    private _enterable = true;
282	    private _zr: ZRenderType;
283	
284	    private _alwaysShowContent: boolean = false;
285	    private _hideTimeout: number;
286	    /**
287	     * Hide delay time
288	     */
289	    private _hideDelay: number;
290	
291	    private _inContent: boolean;
292	    private _firstShow = true;
293	    private _longHide = true;
294	    /**
295	     * Record long-time hide
296	     */
297	    private _longHideTimeout: number;
298	
299	    private _enableDisplayTransition: boolean;
300	
301	    constructor(
302	        api: ExtensionAPI,
303	        opt: TooltipContentOption
304	    ) {
305	        if (env.wxa) {
306	            return null;
307	        }
308	
309	        const el = document.createElement('div');
310	        // TODO: TYPE
311	        (el as any).domBelongToZr = true;
312	        this.el = el;
313	        const zr = this._zr = api.getZr();
314	
315	        const appendTo = opt.appendTo;
316	        const container: HTMLElement | null | undefined = appendTo && (
317	            isString(appendTo)
318	                ? document.querySelector(appendTo)
319	                : isDom(appendTo)
320	                    ? appendTo
321	                    : isFunction(appendTo) && appendTo(api.getDom())
322	        );
323	
324	        makeStyleCoord(this._styleCoord, zr, container, api.getWidth() / 2, api.getHeight() / 2);
325	
326	        (container || api.getDom()).appendChild(el);
327	
328	        this._api = api;
329	        this._container = container;
330	
331	        // FIXME
332	        // Is it needed to trigger zr event manually if
333	        // the browser do not support `pointer-events: none`.
334	
335	        const self = this;
336	        el.onmouseenter = function () {
337	            // clear the timeout in hideLater and keep showing tooltip
338	            if (self._enterable) {
339	                clearTimeout(self._hideTimeout);
340	                self._show = true;
341	            }
342	            self._inContent = true;
343	        };
344	        el.onmousemove = function (e) {
345	            e = e || (window as any).event;
346	            if (!self._enterable) {
347	                // `pointer-events: none` is set to tooltip content div
348	                // if `enterable` is set as `false`, and `el.onmousemove`
349	                // can not be triggered. But in browser that do not
350	                // support `pointer-events`, we need to do this:
351	                // Try trigger zrender event to avoid mouse
352	                // in and out shape too frequently
353	                const handler = zr.handler;
354	                const zrViewportRoot = zr.painter.getViewportRoot();
355	                normalizeEvent(zrViewportRoot, e as ZRRawEvent, true);
356	                handler.dispatch('mousemove', e);
357	            }
358	        };
359	        el.onmouseleave = function () {
360	            // set `_inContent` to `false` before `hideLater`
361	            self._inContent = false;
362	
363	            if (self._enterable) {
364	                if (self._show) {
365	                    self.hideLater(self._hideDelay);
366	                }
367	            }
368	        };
369	    }
370	
371	    /**
372	     * Update when tooltip is rendered
373	     */
374	    update(tooltipModel: Model<TooltipOption>) {
375	        // FIXME
376	        // Move this logic to ec main?
377	        if (!this._container) {
378	            const container = this._api.getDom();
379	            const position = getComputedStyle(container, 'position');
380	            const domStyle = container.style;
381	            if (domStyle.position !== 'absolute' && position !== 'absolute') {
382	                domStyle.position = 'relative';
383	            }
384	        }
385	
386	        // move tooltip if chart resized
387	        const alwaysShowContent = tooltipModel.get('alwaysShowContent');
388	        alwaysShowContent && this._moveIfResized();
389	
390	        // update alwaysShowContent
391	        this._alwaysShowContent = alwaysShowContent;
392	
393	        this._enableDisplayTransition = tooltipModel.get('displayTransition')
394	            && tooltipModel.get('transitionDuration') > 0;
395	
396	        // update className
397	        this.el.className = tooltipModel.get('className') || '';
398	
399	        // Hide the tooltip
400	        // PENDING
401	        // this.hide();
402	    }
403	
404	    show(tooltipModel: Model<TooltipOption>, nearPointColor: ZRColor) {
405	        clearTimeout(this._hideTimeout);
406	        clearTimeout(this._longHideTimeout);
407	        const el = this.el;
408	        const style = el.style;
409	        const styleCoord = this._styleCoord;
410	        if (!el.innerHTML) {
411	            style.display = 'none';
412	        }
413	        else {
414	            style.cssText = gCssText
415	                + assembleCssText(tooltipModel, !this._firstShow, this._longHide, this._enableDisplayTransition)
416	                // initial transform
417	                + assembleTransform(styleCoord[0], styleCoord[1], true)
418	                + `border-color:${convertToColorString(nearPointColor)};`
419	                + (tooltipModel.get('extraCssText') || '')
420	                // If mouse occasionally move over the tooltip, a mouseout event will be
421	                // triggered by canvas, and cause some unexpectable result like dragging
422	                // stop, "unfocusAdjacency". Here `pointer-events: none` is used to solve
423	                // it. Although it is not supported by IE8~IE10, fortunately it is a rare
424	                // scenario.
425	                + `;pointer-events:${this._enterable ? 'auto' : 'none'}`;
426	        }
427	
428	        this._show = true;
429	        this._firstShow = false;
430	        this._longHide = false;
431	    }
432	
433	    setContent(
434	        content: string | HTMLElement | HTMLElement[],
435	        markers: unknown,
436	        tooltipModel: Model<TooltipOption>,
437	        borderColor?: ZRColor,
438	        arrowPosition?: TooltipOption['position']
439	    ) {
440	        const el = this.el;
441	
442	        if (content == null) {
443	            el.innerHTML = '';
444	            return;
445	        }
446	
447	        let arrow = '';
448	        if (isString(arrowPosition) && tooltipModel.get('trigger') === 'item'
449	            && !shouldTooltipConfine(tooltipModel)) {
450	            arrow = assembleArrow(tooltipModel, borderColor, arrowPosition);
451	        }
452	        if (isString(content)) {
453	            el.innerHTML = content + arrow;
454	        }
455	        else if (content) {
456	            // Clear previous
457	            el.innerHTML = '';
458	            if (!isArray(content)) {
459	                content = [content];
460	            }
461	            for (let i = 0; i < content.length; i++) {
462	                if (isDom(content[i]) && content[i].parentNode !== el) {
463	                    el.appendChild(content[i]);
464	                }
465	            }
466	            // no arrow if empty
467	            if (arrow && el.childNodes.length) {
468	                // no need to create a new parent element, but it's not supported by IE 10 and older.
469	                // const arrowEl = document.createRange().createContextualFragment(arrow);
470	                const arrowEl = document.createElement('div');
471	                arrowEl.innerHTML = arrow;
472	                el.appendChild(arrowEl);
473	            }
474	        }
475	    }
476	
477	    setEnterable(enterable: boolean) {
478	        this._enterable = enterable;
479	    }
480	
481	    getSize() {
482	        const el = this.el;
483	        return el ? [el.offsetWidth, el.offsetHeight] : [0, 0];
484	    }
485	
486	    moveTo(zrX: number, zrY: number) {
487	        if (!this.el) {
488	            return;
489	        }
490	        const styleCoord = this._styleCoord;
491	        makeStyleCoord(styleCoord, this._zr, this._container, zrX, zrY);
492	
493	        if (styleCoord[0] != null && styleCoord[1] != null) {
494	            const style = this.el.style;
495	            const transforms = assembleTransform(styleCoord[0], styleCoord[1]) as string[][];
496	            each(transforms, (transform) => {
497	              style[transform[0] as any] = transform[1];
498	            });
499	        }
500	    }
501	
502	    /**
503	     * when `alwaysShowContent` is true,
504	     * move the tooltip after chart resized
505	     */
506	    _moveIfResized() {
507	        // The ratio of left to width
508	        const ratioX = this._styleCoord[2];
509	        // The ratio of top to height
510	        const ratioY = this._styleCoord[3];
511	        this.moveTo(
512	            ratioX * this._zr.getWidth(),
513	            ratioY * this._zr.getHeight()
514	        );
515	    }
516	
517	    hide() {
518	        const style = this.el.style;
519	        if (this._enableDisplayTransition) {
520	            style.visibility = 'hidden';
521	            style.opacity = '0';
522	        }
523	        else {
524	            style.display = 'none';
525	        }
526	        env.transform3dSupported && (style.willChange = '');
527	        this._show = false;
528	        this._longHideTimeout = setTimeout(() => this._longHide = true, 500) as any;
529	    }
530	
531	    hideLater(time?: number) {
532	        if (this._show && !(this._inContent && this._enterable) && !this._alwaysShowContent) {
533	            if (time) {
534	                this._hideDelay = time;
535	                // Set show false to avoid invoke hideLater multiple times
536	                this._show = false;
537	                this._hideTimeout = setTimeout(bind(this.hide, this), time) as any;
538	            }
539	            else {
540	                this.hide();
541	            }
542	        }
543	    }
544	
545	    isShow() {
546	        return this._show;
547	    }
548	
549	    dispose() {
550	        clearTimeout(this._hideTimeout);
551	        clearTimeout(this._longHideTimeout);
552	
553	        const zr = this._zr;
554	        transformLocalCoordClear(zr && zr.painter && zr.painter.getViewportRoot(), this._container);
555	
556	        if (this.el) {
557	            const parentNode = this.el.parentNode;
558	            parentNode && parentNode.removeChild(this.el);
559	        }
560	
561	        this.el = this._container = null;
562	    }
563	
564	}
565	
566	export default TooltipHTMLContent;
